import { File, Directory, Paths } from 'expo-file-system'
import * as MediaLibrary from 'expo-media-library'
import { toast } from '../toast'

interface DownloadParams {
	url: string
	fileName: string
}

export function useSaveToGallery() {
	async function download({
		url,
		fileName
	}: DownloadParams): Promise<string | null> {
		try {
			const { status } = await MediaLibrary.requestPermissionsAsync()
			if (status !== 'granted') {
				toast.show({
					message: 'Photo library permission required',
					variant: 'error'
				})
				return null
			}

			const destinationDir = new Directory(Paths.cache, 'images')
			destinationDir.create({ idempotent: true })

			const downloadedFile = await File.downloadFileAsync(url, destinationDir)

			const savedFile = new File(destinationDir, fileName)
			if (downloadedFile.uri !== savedFile.uri) {
				if (savedFile.exists) {
					savedFile.delete()
				}
				downloadedFile.move(savedFile)
			}

			await MediaLibrary.saveToLibraryAsync(savedFile.uri)

			savedFile.delete()

			toast.show({
				message: 'Image saved to gallery',
				variant: 'success'
			})
			return savedFile.uri
		} catch (error: any) {
			toast.show({
				message: 'Error saving image',
				variant: 'error'
			})
			console.error('Error downloading photo:', error)
			return null
		}
	}

	return { download }
}
